    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Placeholder: just copy the input value; a real implementation would
        // scan along dimension `dim` and store the index of the minimum.
        out[idx] = x[idx];
    }
}

torch::Tensor custom_argmin_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    torch::Tensor out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    argmin_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>, dim, size);

    return out;
}
"""

argmin_cpp_source = "torch::Tensor custom_argmin_cuda(torch::Tensor x, int dim);"

custom_argmin = load_inline(
    name="custom_argmin",
    cpp_sources=argmin_cpp_source,
    cuda_sources=argmin_kernel.cuda_source,
    functions=["custom_argmin_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
